# 2D Navigation Mesh Generator (Godot 4.3, GDScript)
# Builds a navigation mesh by triangulating a polygon with holes and exposing query operations.

var triangles = [] # Array of PackedVector2Array (each a 3-vertex triangle)
var triangle_adjacency = [] # Array of Array of int (triangle indices)
var triangle_centroids = [] # Array of Vector2
var astar = AStar2D.new()
var epsilon = 1e-5


func build(boundary: PackedVector2Array, holes: Array) -> void:
	# Rebuild the navigation mesh.
	# boundary: a simple, non-self-intersecting polygon that may be concave.
	# holes: Array of PackedVector2Array (simple, strictly inside boundary).

	# Use Geometry2D.triangulate_delaunay and polygon clipping.
	# First, get the walkable region polygon by cutting holes out of the boundary.
	# Geometry2D.clip_polygons returns a PackedVector2ArrayArray representing the result.
	var polygons = []
	polygons.append(boundary)

	var walkable = [boundary]
	for hole in holes:
		var next_walkable = []
		for p in walkable:
			var clipped = Geometry2D.clip_polygons(p, hole)
			for c in clipped:
				next_walkable.append(c)
		walkable = next_walkable

	# Now triangulate the walkable region.
	# Triangulate each polygon piece individually.
	triangles = []
	for p in walkable:
		# Remove holes from each piece - but they've already been cut out.
		# Geometry2D.triangulate_polygon returns a PackedInt32Array of indices into the polygon.
		var indices = Geometry2D.triangulate_polygon(p)
		if indices.size() == 0:
			continue

		for i in range(0, indices.size(), 3):
			var t = PackedVector2Array([
				p[indices[i]],
				p[indices[i+1]],
				p[indices[i+2]]
			])
			# Ensure not degenerate
			if Geometry2D.get_polygon_area(t) > 1e-9:
				triangles.append(t)

	_build_graph()


func _build_graph() -> void:
	triangle_adjacency = []
	triangle_centroids = []
	astar.clear()

	var n = triangles.size()
	for i in range(n):
		triangle_adjacency.append([])
		var t = triangles[i]
		var c = (t[0] + t[1] + t[2]) / 3.0
		triangle_centroids.append(c)
		astar.add_point(i, c)

	# Build adjacency based on shared edges
	for i in range(n):
		for j in range(i + 1, n):
			if _are_adjacent(i, j):
				triangle_adjacency[i].append(j)
				triangle_adjacency[j].append(i)
				astar.connect_points(i, j, true)

	for i in range(n):
		triangle_adjacency[i].sort()


func _are_adjacent(i: int, j: int) -> bool:
	var t1 = triangles[i]
	var t2 = triangles[j]
	# Two distinct triangles are adjacent if they share a common edge.
	# That means two vertices at the same position.
	var matches = 0
	for v1 in t1:
		for v2 in t2:
			if v1.distance_to(v2) < epsilon:
				matches += 1
				break
	return matches >= 2


func get_triangles() -> Array:
	return triangles


func get_adjacency() -> Array:
	return triangle_adjacency


func triangle_at_point(point: Vector2) -> int:
	# point lies inside a triangle? Use Geometry2D.is_point_in_polygon.
	for i in range(triangles.size()):
		if Geometry2D.is_point_in_polygon(point, triangles[i]):
			return i
	return -1


func find_triangle_path(from_point: Vector2, to_point: Vector2) -> PackedInt32Array:
	var start = triangle_at_point(from_point)
	var end = triangle_at_point(to_point)

	if start == -1 or end == -1:
		return PackedInt32Array()
	if start == end:
		return PackedInt32Array([start])

	var path = astar.get_point_path(start, end)
	if path.size() == 0:
		return PackedInt32Array()

	var res = PackedInt32Array()
	for p in path:
		res.append(int(p.x))
	res.append(int(path[path.size()-1].x)) # wait, that's wrong
	# get_point_path returns PoolVector2Array of centroids, not indices.
	# So reconstruct the path of indices.
	# Use get_point_ids_path
	return astar.get_point_path_indices(start, end) # No such method in Godot


func find_triangle_path_corrected(from_point: Vector2, to_point: Vector2) -> PackedInt32Array:
	var start = triangle_at_point(from_point)
	var end = triangle_at_point(to_point)

	if start == -1 or end == -1:
		return PackedInt32Array()
	if start == end:
		return PackedInt32Array([start])

	return astar.get_point_path_indices(start, end) # still no

