# 2D Navigation Mesh Generator (Godot 4.3, GDScript)
# Triangulates a polygon with holes by connecting holes to the boundary.

var triangles = []
var triangle_adjacency = []
var triangle_centroids = []
var astar = AStar2D.new()
var epsilon = 1e-5


func build(boundary: PackedVector2Array, holes: Array) -> void:
	# 1. Normalize winding: ensure all holes have the same winding as boundary.
	var b = boundary
	var b_ccw = Geometry2D.is_polygon_clockwise(b) == false
	var processed_holes = []
	for h in holes:
		var h_ccw = Geometry2D.is_polygon_clockwise(h) == false
		if h_ccw != b_ccw:
			var hr = PackedVector2Array()
			for i in range(h.size()-1, -1, -1):
				hr.append(h[i])
			h = hr
		processed_holes.append(h)

	# 2. Connect all holes to the boundary to form a single polygon.
	# Since holes are strictly inside and don't touch, we can connect each hole to the boundary independently.
	# We connect the hole to the boundary at the closest point.
	# For multiple holes, we just connect each directly to the current boundary.
	var poly = b
	for h in processed_holes:
		poly = _connect_hole_to_boundary(poly, h)

	# 3. Triangulate the resulting single polygon.
	triangles = []
	var indices = Geometry2D.triangulate_polygon(poly)
	for i in range(0, indices.size(), 3):
		var t = PackedVector2Array([
			poly[indices[i]],
			poly[indices[i+1]],
			poly[indices[i+2]]
		])
		if _poly_area(t) > 1e-9:
			triangles.append(t)

	_build_graph()


func _connect_hole_to_boundary(boundary: PackedVector2Array, hole: PackedVector2Array) -> PackedVector2Array:
	# Find the vertex in the hole and the edge on the boundary that are closest.
	var best_dist = INF
	var best_hole_idx = -1
	var best_boundary_edge_idx = -1
	var best_split_point = Vector2.INF

	for i in range(hole.size()):
		var v_h = hole[i]
		for j in range(boundary.size()):
			var v1 = boundary[j]
			var v2 = boundary[(j + 1) % boundary.size()]
			var p = Geometry2D.get_closest_point_to_segment(v_h, v1, v2)
			var d = v_h.distance_squared_to(p)
			if d < best_dist:
				best_dist = d
				best_hole_idx = i
				best_boundary_edge_idx = j
				best_split_point = p

	# Split the boundary edge and insert the hole polygon.
	var new_poly = PackedVector2Array()
	var b_size = boundary.size()
	for i in range(b_size + 1):
		# If this is the edge to split, insert the split point first.
		if i == best_boundary_edge_idx:
			new_poly.append(boundary[i])
			new_poly.append(best_split_point)
			# Now insert the hole path, starting at the best hole vertex,
			# going around the hole, and returning to the best hole vertex,
			# then back to the split point, then to the next boundary vertex.
			# But wait, we need to connect the split point to the hole vertex.
			# So: split_point -> best_hole_vertex -> ...hole -> best_hole_vertex -> split_point.
			new_poly.append(best_split_point)
			for k in range(hole.size()):
				new_poly.append(hole[(best_hole_idx + k) % hole.size()])
			new_poly.append(hole[best_hole_idx])
			new_poly.append(best_split_point)
		elif i < b_size:
			new_poly.append(boundary[i])

	return new_poly


func _poly_area(p: PackedVector2Array) -> float:
	var area = 0.0
	var n = p.size()
	for i in range(n):
		var v1 = p[i]
		var v2 = p[(i + 1) % n]
		area += (v1.x * v2.y - v2.x * v1.y)
	return abs(area) * 0.5


func _build_graph() -> void:
	triangle_adjacency = []
	triangle_centroids = []
	astar.clear()

	var n = triangles.size()
	for i in range(n):
		triangle_adjacency.append([])
		var t = triangles[i]
		var c = (t[0] + t[1] + t[2]) / 3.0
		triangle_centroids.append(c)
		astar.add_point(i, c)

	for i in range(n):
		for j in range(i + 1, n):
			if _are_adjacent(i, j):
				triangle_adjacency[i].append(j)
				triangle_adjacency[j].append(i)
				astar.connect_points(i, j, true)

	for i in range(n):
		triangle_adjacency[i].sort()


func _are_adjacent(i: int, j: int) -> bool:
	var t1 = triangles[i]
	var t2 = triangles[j]
	var matches = 0
	for v1 in t1:
		for v2 in t2:
			if v1.distance_to(v2) < epsilon:
				matches += 1
				break
	return matches >= 2


func get_triangles() -> Array:
	return triangles


func get_adjacency() -> Array:
	return triangle_adjacency


func triangle_at_point(point: Vector2) -> int:
	for i in range(triangles.size()):
		if Geometry2D.is_point_in_polygon(point, triangles[i]):
			return i
	return -1


func find_triangle_path(from_point: Vector2, to_point: Vector2) -> PackedInt32Array:
	var start = triangle_at_point(from_point)
	var end = triangle_at_point(to_point)

	if start == -1 or end == -1:
		return PackedInt32Array()
	if start == end:
		return PackedInt32Array([start])

	var path = astar.get_id_path(start, end)
	var res = PackedInt32Array()
