			var t1 = t[i]
			var t2 = t[(i + 1) % 3]
			for j in range(h.size()):
				var h1 = h[j]
				var h2 = h[(j + 1) % h.size()]
				var inter = Geometry2D.get_closest_points_between(t1, t2, h1, h2)
				# If distance is < epsilon, they intersect.
				# Actually, intersection at a single point on the boundary is okay.
				# We only care about overlap. Intersection points are okay if they're on edges.
				# This is hard. Actually, intersection of edges is only a problem if it's in the interior.
