var astar = AStar2D.new()
var epsilon = 1e-5


func build(boundary: PackedVector2Array, holes: Array) -> void:
	var raw_triangles = []
	var indices = Geometry2D.triangulate_polygon(boundary)
	for i in range(0, indices.size(), 3):
		var t = PackedVector2Array([
			boundary[indices[i]],
			boundary[indices[i+1]],
			boundary[indices[i+2]]
		])
		if _poly_area(t) > 1e-9:
			raw_triangles.append(t)

	triangles = []
	for t in raw_triangles:
		var c = (t[0] + t[1] + t[2]) / 3.0
		# 1. Centroid must be inside boundary
		if not Geometry2D.is_point_in_polygon(c, boundary):
			continue

		# 2. Centroid must not be in any hole
		var in_hole = false
		for h in holes:
			if Geometry2D.is_point_in_polygon(c, h):
				in_hole = true
				break
		if in_hole:
			continue

		# 3. No part of the triangle may cover a hole interior.
		# A triangle is invalid if it has a non-empty intersection with any hole.
		var overlaps = false
		for h in holes:
			var inter = Geometry2D.intersect_polygons(t, h)
			if inter.size() > 0:
				# Check if the intersection has any non-negligible area.
				var area = 0.0
				for piece in inter:
					area += _poly_area(piece)
				if area > epsilon:
					overlaps = true
					break
		if overlaps:
			continue

		triangles.append(t)

	_build_graph()


func _poly_area(p: PackedVector2Array) -> float:
	var area = 0.0
	var n = p.size()
	for i in range(n):
		var v1 = p[i]
		var v2 = p[(i + 1) % n]
		area += (v1.x * v2.y - v2.x * v1.y)
	return abs(area) * 0.5


# --- The rest is the same ---

func _build_graph() -> void:
	triangle_adjacency = []
	triangle_centroids = []
	astar.clear()
	var n = triangles.size()
	for i in range(n):
		triangle_adjacency.append([])
		var t = triangles[i]
		var c = (t[0] + t[1] + t[2]) / 3.0
		triangle_centroids.append(c)
		astar.add_point(i, c)
	for i in range(n):
		for j in range(i + 1, n):
			if _are_adjacent(i, j):
				triangle_adjacency[i].append(j)
				triangle_adjacency[j].append(i)
				astar.connect_points(i, j, true)
	for i in range(n):
		triangle_adjacency[i].sort()


func _are_adjacent(i: int, j: int) -> bool:
	var t1 = triangles[i]
	var t2 = triangles[j]
	var matches = 0
	for v1 in t1:
		for v2 in t2:
			if v1.distance_to(v2) < epsilon:
				matches += 1
				break
	return matches >= 2


func get_triangles() -> Array:
	return triangles


func get_adjacency() -> Array:
	return triangle_adjacency


func triangle_at_point(point: Vector2) -> int:
	for i in range(triangles.size()):
		if Geometry2D.is_point_in_polygon(point, triangles[i]):
			return i
	return -1


func find_triangle_path(from_point: Vector2, to_point: Vector2) -> PackedInt32Array:
	var start = triangle_at_point(from_point)
	var end = triangle_at_point(to_point)
	if start == -1 or end == -1:
		return PackedInt32Array()
	if start == end:
