# 2D Navigation Mesh Generator (Godot 4.3, GDScript)
# Triangulates a polygon with holes using NavigationPolygon outlining,
# which correctly cuts holes.

var triangles = []
var triangle_adjacency = []
var triangle_centroids = []
var astar = AStar2D.new()
var epsilon = 1e-5


func build(boundary: PackedVector2Array, holes: Array) -> void:
	# 1. Normalize winding: boundary CCW, holes CW.
	# Geometry2D.is_polygon_clockwise returns true for clockwise.
	var b = boundary
	if Geometry2D.is_polygon_clockwise(b):
		var br = PackedVector2Array()
		for i in range(b.size()-1, -1, -1):
			br.append(b[i])
		b = br

	var processed_holes = []
	for h in holes:
		if not Geometry2D.is_polygon_clockwise(h):
			var hr = PackedVector2Array()
			for i in range(h.size()-1, -1, -1):
				hr.append(h[i])
			h = hr
		processed_holes.append(h)

	# 2. Build NavigationPolygon outlines to cut holes.
	var np = NavigationPolygon.new()
	np.add_outline(b)
	for h in processed_holes:
		np.add_outline(h)
	np.make_polygons_from_outlines()

	# 3. Triangulate each output polygon into triangles.
	# make_polygons_from_outlines returns the walkable region as a set of convex polygons.
	triangles = []
	for i in range(np.get_polygon_count()):
		var p = np.get_polygon(i)
		# p is an array of indices into np's vertices array. Convert to world positions.
		var poly = PackedVector2Array()
		for idx in p:
			poly.append(np.get_vertices()[idx])

		# Triangulate each convex piece.
		var indices = Geometry2D.triangulate_polygon(poly)
		for k in range(0, indices.size(), 3):
			var t = PackedVector2Array([
				poly[indices[k]],
				poly[indices[k+1]],
				poly[indices[k+2]]
			])
			if _poly_area(t) > 1e-9:
				triangles.append(t)

	_build_graph()


