extends RefCounted

# 2D Navigation Mesh Generator (Godot 4.3, GDScript)
# Triangulates the walkable region by creating a single polygon (boundary
# minus holes, with a non-zero-width bridge cut for each hole) and then
# triangulating it, finally filtering out triangles that cover holes.

var triangles = []
var triangle_adjacency = []
var triangle_centroids = []
var astar = AStar2D.new()
var epsilon = 1e-5
var offset = 0.05


func build(boundary: PackedVector2Array, holes: Array) -> void:
	var b = boundary
	if Geometry2D.is_polygon_clockwise(b):
		var br = PackedVector2Array()
		for i in range(b.size()-1, -1, -1):
			br.append(b[i])
		b = br

	var processed_holes = []
	for h in holes:
		if not Geometry2D.is_polygon_clockwise(h):
			var hr = PackedVector2Array()
			for i in range(h.size()-1, -1, -1):
				hr.append(h[i])
			h = hr
		processed_holes.append(h)

	# Grow/shrink each hole by a tiny offset to make the bridge cut non-zero-width.
	# For a CW hole, offset < 0 shrinks it inward (more walkable), giving the
	# bridge cut a non-zero width for reliable triangulation.
	var offset_holes = []
	for h in processed_holes:
		var o = Geometry2D.offset_polygon(h, -offset)
		# offset_polygon returns PackedVector2ArrayArray, take the first piece.
		if o.size() > 0:
			offset_holes.append(o[0])
		else:
			offset_holes.append(h)

	var merged = b
	for h in offset_holes:
		merged = _connect_hole_to_polygon(merged, h)

	var raw_triangles = []
	var indices = Geometry2D.triangulate_polygon(merged)
	for i in range(0, indices.size(), 3):
		var t = PackedVector2Array([
			merged[indices[i]],
			merged[indices[i+1]],
			merged[indices[i+2]]
		])
		if _poly_area(t) > 1e-9:
			raw_triangles.append(t)

	triangles = []
	for t in raw_triangles:
		var c = (t[0] + t[1] + t[2]) / 3.0
		if not Geometry2D.is_point_in_polygon(c, boundary):
			continue

		var in_hole = false
		for h in holes:
			if Geometry2D.is_point_in_polygon(c, h):
				in_hole = true
				break
		if in_hole:
			continue

		# Also check the triangle doesn't cover a hole interior.
		var overlaps = false
		for h in holes:
			var inter = Geometry2D.intersect_polygons(t, h)
			if inter.size() > 0:
				var area = 0.0
				for piece in inter:
					area += _poly_area(piece)
				if area > epsilon:
					overlaps = true
					break
		if overlaps:
			continue

		triangles.append(t)

	_build_graph()


func _connect_hole_to_polygon(poly: PackedVector2Array, hole: PackedVector2Array) -> PackedVector2Array:
	var right_idx = 0
	for i in range(1, hole.size()):
		if hole[i].x > hole[right_idx].x:
			right_idx = i
	var hole_v = hole[right_idx]

	var best_dist = INF
	var best_edge = -1
	var best_p = Vector2.INF
	for i in range(poly.size()):
		var v1 = poly[i]
		var v2 = poly[(i + 1) % poly.size()]
		var p = Geometry2D.get_closest_point_to_segment(hole_v, v1, v2)
		var d = hole_v.distance_squared_to(p)
		if d < best_dist:
			best_dist = d
			best_edge = i
			best_p = p

	var new_poly = PackedVector2Array()
	for i in range(poly.size() + 1):
		if i == best_edge:
			new_poly.append(poly[i])
			# Cut into hole, around, back to the same point.
			new_poly.append(best_p)
			for k in range(hole.size()):
				new_poly.append(hole[(right_idx + k) % hole.size()])
			new_poly.append(hole[right_idx])
			new_poly.append(best_p)
		elif i < poly.size():
			new_poly.append(poly[i])
	return new_poly


func _poly_area(p: PackedVector2Array) -> float:
	var area = 0.0
	var n = p.size()
	for i in range(n):
		var v1 = p[i]
		var v2 = p[(i + 1) % n]
		area += (v1.x * v2.y - v2.x * v1.y)
	return abs(area) * 0.5


# --- The rest is the same ---

func _build_graph() -> void:
	triangle_adjacency = []
	triangle_centroids = []
	astar.clear()
	var n = triangles.size()
	for i in range(n):
		triangle_adjacency.append([])
		var t = triangles[i]
		var c = (t[0] + t[1] + t[2]) / 3.0
		triangle_centroids.append(c)
		astar.add_point(i, c)
	for i in range(n):
		for j in range(i + 1, n):
			if _are_adjacent(i, j):
				triangle_adjacency[i].append(j)
				triangle_adjacency[j].append(i)
				astar.connect_points(i, j, true)
	for i in range(n):
		triangle_adjacency[i].sort()


func _are_adjacent(i: int, j: int) -> bool:
	var t1 = triangles[i]
	var t2 = triangles[j]
	var matches = 0
	for v1 in t1:
		for v2 in t2:
			if v1.distance_to(v2) < epsilon:
				matches += 1
				break
	return matches >= 2


func get_triangles() -> Array:
	return triangles


func get_adjacency() -> Array:
	return triangle_adjacency


func triangle_at_point(point: Vector2) -> int:
	for i in range(triangles.size()):
		if Geometry2D.is_point_in_polygon(point, triangles[i]):
			return i
	return -1


func find_triangle_path(from_point: Vector2, to_point: Vector2) -> PackedInt32Array:
	var start = triangle_at_point(from_point)
	var end = triangle_at_point(to_point)
	if start == -1 or end == -1:
		return PackedInt32Array()
	if start == end:
		return PackedInt32Array([start])
	var path = astar.get_id_path(start, end)
	var res = PackedInt32Array()
	for id in path:
		res.append(int(id))
	return res

