		var p = np.get_polygon(i)
		var poly = PackedVector2Array()
		for idx in p: poly.append(verts[idx])
		# Triangulate each convex piece
		var idxs = Geometry2D.triangulate_polygon(poly)
		for k in range(0, idxs.size(), 3):
			var t = PackedVector2Array([poly[idxs[k]],poly[idxs[k+1]],poly[idxs[k+2]]])
			ts.append(t)
	print("triangles: ", ts.size())
	for i in range(min(ts.size(),20)):
		var t = ts[i]
