func _poly_area(p):
	var a=0.0
	var n=p.size()
	for i in range(n):
		a+=(p[i].x*p[(i+1)%n].y - p[(i+1)%n].x*p[i].y)
	return abs(a)*0.5
func _covers(ts, p):
	for t in ts:
		if Geometry2D.is_point_in_polygon(p, t): return true
	return false
